python3 -c "
import re
dmz_subnets = ['10.0.1.0/24', '192.168.100.0/24']
internal_pattern = re.compile(r'(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)')
with open('firewall-policy.txt') as f:
    for line in f:
        if 'permit' in line.lower() and internal_pattern.search(line):
            if not any(dmz in line for dmz in dmz_subnets):
                print('INTERNAL REACH:', line.strip())
"
